// Isolated process: legacy UI suites mock the shared Supabase module globally.
import { GlobalRegistrator } from '@happy-dom/global-registrator';
import { mock } from 'bun:test';
import assert from 'node:assert/strict';
GlobalRegistrator.register({url:'https://sensor-pal-tester.lovable.app/'});
const calls:{name:string;args:any}[]=[];
mock.module('../../src/lib/standex/supabase',()=>({supabase:{rpc:async(name:string,args:any)=>{calls.push({name,args});return {error:null};}}}));
const usage=await import('../../src/lib/usage/client');
usage.trackUsage('visit');await usage.flushUsage();
assert.equal(calls.length,0);
assert.equal(localStorage.getItem('standex.usage.visitor.v1'),null);
usage.setUsageChoice('no');usage.trackUsage('workshop_opened');await usage.flushUsage();
assert.equal(calls.length,0);
usage.setUsageChoice('yes');usage.setUsageFlow(crypto.randomUUID());
usage.trackUsage('workshop_opened',{source:'basic',answer:'private'} as any);
await usage.flushUsage();
const events=calls.flatMap(c=>c.args._events??[]);
assert(events.some(e=>e.name==='visit'));
assert(events.some(e=>e.name==='project_started'));
assert(events.some(e=>e.name==='workshop_opened'));
assert(!JSON.stringify(calls).includes('private'));
usage.trackUsage('submission_attempted');await usage.bindUsageSubmission(crypto.randomUUID());
assert.equal(calls.at(-1)!.name,'product_usage_bind');
assert(calls.slice(0,-1).some(c=>c.args._events?.some((e:any)=>e.name==='submission_attempted')));
const before=calls.length;
usage.trackUsage('trial_started');usage.setUsageChoice('no');await usage.flushUsage();
assert.equal(calls.length,before);
assert.equal(localStorage.getItem('standex.usage.visitor.v1'),null);
assert.equal(sessionStorage.getItem('standex.usage.outbox.v1'),null);
history.replaceState({},'', '/?usage=off');
usage.setUsageChoice('yes');usage.trackUsage('visit');await usage.flushUsage();
assert.equal(calls.length,before);
assert.equal(usage.usageAllowedHost('localhost'),false);
assert.equal(usage.usageAllowedHost('id-preview--example.lovable.app'),false);
console.log('Consent, withdrawal, allowlist, safe properties, baseline and ordered binding verified.');
process.exit(0);
